window.Webflow = window.Webflow || [];
window.Webflow.push(function () {
  if (!window.gsap || !window.Flip || !window.jQuery) return;

  gsap.registerPlugin(Flip);

  $(".nav-wrapper").each(function () {
    /* === EASY ADJUSTMENTS ===
       flipDuration   → menu open/close speed
       linksDuration  → menu link reveal speed
       linksEach      → stagger between menu links
       linksStart     → when links start
       hoverScale     → scale amount on menu link hover
       hoverSpeed     → hover animation speed
    */

    let hamburgerEl   = $(this).find(".nav-hamburger-wrap");
    let menuContainEl = $(this).find(".menu-contain");
    let flipItemEl    = $(this).find(".nav-hamburger-base");
    let menuWrapEl    = $(this).find(".menu-wrap");
    let menuBaseEl    = $(this).find(".menu-base");

    let menuLinkEl    = $(this).find(".menu-link");
    let navLineEl     = $(this).find(".nav-line");
    let socialGroupEl = $(this).find(".social-group");

    let navMenuTextEl  = $(this).find(".nav-main-text").not(".close");
    let navCloseTextEl = $(this).find(".nav-main-text.close");

    let flipDuration   = 0.42;
    let linksDuration  = 0.12;
    let linksEach      = 0.055;
    let linksStart     = 0.14;

    let lineDuration   = 0.16;
    let socialDuration = 0.16;

    let hoverScale     = 1.05;
    let hoverSpeed     = 0.22;

    if (!hamburgerEl.length || !flipItemEl.length) return;

    let closeOriginalParent = navCloseTextEl.length ? navCloseTextEl.parent()[0] : null;

    /* =====================================================
       ONLY CHANGE IN THIS ENTIRE SCRIPT:
       If .nav-hamburger-base is white, make Close text red.
       Everything else remains EXACTLY the same.
    ===================================================== */
    function hamburgerIsWhite() {
      // Prefer the existing `.white` class if you use it
      if (flipItemEl.find(".white").length) return true;

      // Fallback to computed background color on the base
      let bg = window.getComputedStyle(flipItemEl[0]).backgroundColor;
      return bg === "rgb(255, 255, 255)" || bg === "rgba(255, 255, 255, 1)";
    }

    function setMenuTextState(isOpen) {
      gsap.set(navMenuTextEl, {
        opacity: isOpen ? 0 : 1,
        pointerEvents: isOpen ? "none" : "auto"
      });

      if (!navCloseTextEl.length) return;

      if (isOpen) {
        navCloseTextEl.appendTo(menuWrapEl);
        gsap.set(navCloseTextEl, {
          pointerEvents: "auto",
          opacity: 1,
          zIndex: 999999999,
          right: "2rem",
          top: "2rem",
          // ✅ ONLY EDIT: conditional Close color
          color: hamburgerIsWhite() ? "red" : "white",
          position: "absolute"
        });

        // IMPORTANT: prevent the "Close" click from also triggering the hamburger click
        navCloseTextEl.off("click._closefix").on("click._closefix", function (e) {
          e.preventDefault();
          e.stopPropagation();
          openMenu(false);
        });
      } else {
        if (closeOriginalParent) navCloseTextEl.appendTo(closeOriginalParent);
        gsap.set(navCloseTextEl, {
          pointerEvents: "none",
          opacity: 0,
          position: "",
          top: "",
          right: "",
          color: "",
          zIndex: ""
        });
      }
    }

    function setClosedStates() {
      gsap.set(menuLinkEl, { opacity: 0, y: 12, scale: 1, transformOrigin: "50% 50%" });
      if (navLineEl.length) gsap.set(navLineEl, { opacity: 0, y: 10, visibility: "hidden" });
      if (socialGroupEl.length) gsap.set(socialGroupEl, { opacity: 0, y: 10, visibility: "hidden" });
    }

    setClosedStates();
    gsap.set(menuWrapEl, { display: "none" });
    gsap.set(menuBaseEl, { opacity: 0 });

    // Page-load text state
    setMenuTextState(false);

    function flip(forwards) {
      let state = Flip.getState(flipItemEl);
      flipItemEl.appendTo(forwards ? menuContainEl : hamburgerEl);
      Flip.from(state, { duration: flipDuration });
    }

    let tl = gsap.timeline({ paused: true });

    // Force hidden states before menu becomes visible (prevents flash)
    tl.set(menuLinkEl, { opacity: 0, y: 12, scale: 1 }, 0);
    if (navLineEl.length) tl.set(navLineEl, { opacity: 0, y: 10, visibility: "hidden" }, 0);
    if (socialGroupEl.length) tl.set(socialGroupEl, { opacity: 0, y: 10, visibility: "hidden" }, 0);

    tl.set(menuWrapEl, { display: "flex" }, 0);

    tl.fromTo(
      menuBaseEl,
      { opacity: 0 },
      {
        opacity: 1,
        duration: flipDuration,
        ease: "none",
        onStart: () => {
          setMenuTextState(true);
          flip(true);
        }
      },
      0
    );

    // Menu links (staggered)
    tl.fromTo(
      menuLinkEl,
      { opacity: 0, y: 12, scale: 1 },
      {
        opacity: 1,
        y: 0,
        scale: 1,
        duration: linksDuration,
        stagger: { each: linksEach },
        immediateRender: false
      },
      linksStart
    );

    // Nav line AFTER all links (55% opacity)
    if (navLineEl.length) {
      tl.fromTo(
        navLineEl,
        { opacity: 0, y: 10, visibility: "hidden" },
        {
          opacity: 0.55,
          y: 0,
          visibility: "visible",
          duration: lineDuration,
          immediateRender: false
        },
        ">"
      );
    }

    // Social group AFTER line
    if (socialGroupEl.length) {
      tl.fromTo(
        socialGroupEl,
        { opacity: 0, y: 10, visibility: "hidden" },
        {
          opacity: 1,
          y: 0,
          visibility: "visible",
          duration: socialDuration,
          immediateRender: false
        },
        ">"
      );
    }

    tl.eventCallback("onReverseComplete", function () {
      flip(false);
      setMenuTextState(false);
      gsap.set(menuWrapEl, { display: "none" });
      setClosedStates();
    });

    function openMenu(open) {
      if (tl.isActive()) return;

      if (open) {
        setClosedStates();
        gsap.set(menuBaseEl, { opacity: 0 });
        gsap.set(menuWrapEl, { display: "flex" });
        tl.play(0);
        hamburgerEl.addClass("nav-open");
      } else {
        tl.reverse();
        hamburgerEl.removeClass("nav-open");
      }
    }

    // Hamburger click toggles menu
    hamburgerEl.on("click", function (e) {
      e.preventDefault();
      openMenu(!hamburgerEl.hasClass("nav-open"));
    });

    // Close interactions
    menuBaseEl.on("mouseenter", function () {
      openMenu(false);
    });

    menuBaseEl.on("click", function (e) {
      e.preventDefault();
      openMenu(false);
    });

    $(document).on("keydown", function (e) {
      if (e.key === "Escape") openMenu(false);
    });

    /* === SMOOTH SCALE HOVER FOR MENU LINKS === */
    menuLinkEl.each(function () {
      let el = this;

      el.addEventListener("mouseenter", () => {
        gsap.to(el, {
          scale: hoverScale,
          duration: hoverSpeed,
          ease: "power2.out",
          overwrite: "auto"
        });
      });

      el.addEventListener("mouseleave", () => {
        gsap.to(el, {
          scale: 1,
          duration: hoverSpeed,
          ease: "power2.out",
          overwrite: "auto"
        });
      });
    });
  });
});

