      var x = Math.sin(a) * radiusX;
      var y = (1 - Math.cos(a)) * radiusY;
      var rot = (rel * step) * CFG.rotateFactor;

      var dist = Math.min(absRel, 4);
      var tt = dist / 4;
      var scale = (1 - tt) * (1 - CFG.scaleMin) + CFG.scaleMin;

