  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  var wrap = document.querySelector(".content-wrapper.hand-with-bag");
  if (!wrap) return;

  var leftHand = wrap.querySelector(".content-block.hand-with-bag._01");
  var rightHand = wrap.querySelector(".content-block.hand-with-bag._02");
  if (!leftHand || !rightHand) return;

  if (reduceMotion) {
    gsap.set([leftHand, rightHand], { clearProps: "transform" });
    return;
  }

  gsap.set(leftHand, {
    x: "-22vw",
    y: "10vh",
    rotateZ: -10,
    z: -160,
    force3D: true,
    willChange: "transform",
    overwrite: true
  });

  gsap.set(rightHand, {
    x: "22vw",
    y: "10vh",
    rotateZ: 10,
    z: -160,
    force3D: true,
    willChange: "transform",
    overwrite: true
  });

  gsap.timeline({
    defaults: { ease: "none" }, // ⬅ true parallax smoothness
    scrollTrigger: {
      trigger: wrap,
      start: "top 80%",   // ⬅ starts a bit later
      end: "top 25%",     // ⬅ MUCH longer scroll distance
      scrub: 1.6,         // ⬅ slow + buttery interpolation
      invalidateOnRefresh: true
      // markers: true
    }
  })
  .to(leftHand, { x: 0, y: 0, rotateZ: 0, z: 0, overwrite: true }, 0)
  .to(rightHand, { x: 0, y: 0, rotateZ: 0, z: 0, overwrite: true }, 0);
