/* =========================================================
   SNAXX HERO — FAST FLOATING CHIPS (NOTICEABLE)
========================================================= */

window.Webflow = window.Webflow || [];
window.Webflow.push(function () {
  if (!window.gsap) return;

  var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  var hero = document.querySelector("section.section.red-text");
  if (!hero) return;

  var stars = hero.querySelector(".review-5-stars");
  var h1a = hero.querySelector(".h1-heading.home-hero:not(._02)");
  var h1b = hero.querySelector(".h1-heading.home-hero._02");
  var cta = hero.querySelector(".button-container-03");
  var contentWrap = hero.querySelector(".content-wrapper.home-hero");

  var order = ["chip-01", "chip-02", "chip-03", "chip-04"];
  var chips = order.map(c => hero.querySelector(".image-wrapper." + c)).filter(Boolean);

  if (!contentWrap || !h1a || !h1b || !cta) return;

  /* ===============================
     3D CONTEXT
  =============================== */
  gsap.set(hero, { perspective: 1200, transformStyle: "preserve-3d" });
  gsap.set(contentWrap, { transformStyle: "preserve-3d" });
  chips.forEach(el => gsap.set(el, { transformStyle: "preserve-3d" }));

  /* ===============================
     REDUCED MOTION
  =============================== */
  if (reduceMotion) {
    gsap.set([stars, h1a, h1b, cta, ...chips], { opacity: 1, clearProps: "transform,filter" });
    return;
  }

  /* ===============================
     INITIAL STATES
  =============================== */
  const contentItems = [stars, h1a, h1b, cta];

  gsap.set(contentItems, {
    opacity: 0,
    y: -140,
    x: -10,
    skewY: 10,
    skewX: -8,
    rotateZ: -6,
    rotateX: 18,
    z: -60,
    filter: "blur(8px)",
    force3D: true
  });

  chips.forEach((el, i) => {
    const dir = i % 2 === 0 ? -1 : 1;
    gsap.set(el, {
      opacity: 0,
      y: -180,
      x: 30 * dir,
      skewY: 12,
      skewX: -10 * dir,
      rotateZ: -10 * dir,
      rotateX: 26,
      rotateY: 18 * dir,
      z: -140,
      scale: 0.9,
      filter: "blur(10px)",
      force3D: true
    });
  });

  /* ===============================
     REVEAL TIMELINE
  =============================== */
  const tl = gsap.timeline({ delay: 0.08, defaults: { ease: "power3.out" } });

  tl.to(contentItems, {
    opacity: 1,
    y: 0,
    x: 0,
    skewY: 0,
    skewX: 0,
    rotateZ: 0,
    rotateX: 0,
    z: 0,
    filter: "blur(0px)",
    duration: 0.95,
    stagger: 0.18,
    ease: "power4.out"
  }, 0);

  tl.to(chips, {
    opacity: 1,
    y: 0,
    x: 0,
    skewY: 0,
    skewX: 0,
    rotateZ: 0,
    rotateX: 0,
    rotateY: 0,
    z: 0,
    scale: 1,
    filter: "blur(0px)",
    duration: 1.05,
    stagger: 0.16,
    ease: "back.out(1.35)"
  }, 0.28);

  /* ===============================
     FAST, NOTICEABLE FLOATING
  =============================== */
  function startFloating() {
    chips.forEach(el => gsap.killTweensOf(el, "y"));

    const floats = [
      { y: 34, d: 1.6, delay: 0.0 },
      { y: 40, d: 1.9, delay: 0.15 },
      { y: 36, d: 1.8, delay: 0.3 },
      { y: 44, d: 2.2, delay: 0.45 }
    ];

    chips.forEach((el, i) => {
      const f = floats[i] || floats[0];
      gsap.to(el, {
        y: "+=" + f.y,
        duration: f.d,
        ease: "sine.inOut",
        yoyo: true,
        repeat: -1,
        delay: f.delay
      });
    });
  }

  // Start floating AFTER reveal finishes
  tl.call(startFloating, null, 1.55);
});

